from html.parser import HTMLParser
VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class P(HTMLParser):
    def __init__(s):
        super().__init__(convert_charrefs=True); s.stack=[]; s.err=[]
    def handle_starttag(s,t,a):
        if t not in VOID: s.stack.append((t,s.getpos()))
    def handle_startendtag(s,t,a): pass
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack: s.err.append(('extra close',t,s.getpos())); return
        top=s.stack[-1]
        if top[0]!=t:
            s.err.append(('mismatch: expected %s (opened line %d) got /%s'%(top[0],top[1][0],t), s.getpos()))
